processor-info.script:

String cmd = input.getText("cmd");

String search_gbn_hcode = input.getText("search_gbn_hcode");
String search_gbn_jicode = input.getText("search_gbn_jicode");
String search_user_nm = input.getText("search_user_nm");
String search_user_id = input.getText("search_user_id");
String search_corp_nm = input.getText("search_corp_nm");
String search_mem_div = input.getText("search_mem_div");

if( "getMemberList".equals(cmd))
{
	if( !"".equals(search_gbn_hcode))
		input.put("strHcode", "AND b.hcode = '" + search_gbn_hcode + "'" );

	if( !"".equals(search_gbn_jicode))
		input.put("strJicode", "AND b.ji_code = '" + search_gbn_jicode + "'" );

	if( !"".equals(search_user_nm) )
		input.put("strUserName", "AND a.user_nm like '%" + search_user_nm + "%'" );	

	if( !"".equals(search_user_id) )
		input.put("strUserId", "AND a.user_id like '%" + search_user_id + "%'" );		

	if( !"".equals(search_corp_nm) )
		input.put("strCorpName", "AND b.company like '%" + search_corp_nm + "%'" );	

	if( !"".equals(search_mem_div) )
		input.put("strMemDiv", "AND a.mem_div = '" + search_mem_div + "'" );
}


if("CREATE_MEMBER".equals(cmd) ){

	executeSQL("MEM_INFO", connection, input, output);
	int cnt = output.getCount("user_id");

	if( cnt == 0 )
	{
		executeSQL(cmd, connection, input, output);

		String re_yn = input.getText("re_yn");

		if("Y".equals( re_yn ) )
		{						
			executeSQL("GET_CURRENT_KEY", connection, input, output);
			String user_seq_no = output.getText("user_seq_no");
			input.put("user_seq_no", user_seq_no);					
			executeSQL("INSERT_MEMBER_REQ", connection, input, output);							
		}
	}
}else{
	executeSQL(cmd, connection, input, output);

}

sql.query:
SELECT TOP (?) user_seq_no,user_id,password,ssn,user_nm,corp_nm, corp_reg_no,addr,tel_no,email,cp_code,ill_no,mem_div, building_nm,building_addr,zipcode,building_zipcode, post_zipcode,post_addr,post_req,post_tel_no,remark,account_nm,trans_yn, birth_yyyy,birth_mm,birth_dd, corp_tel_no,corp_fax_no,building_tel_no,building_fax_no,sex,addr_nm, hcode,ji_code, (select top (1) BASE_NAME from TB_APC_BASE_CODE where BASE_CODE = hcode and GROUP_CODE = '21' ) as hname, (select top (1) JISANAME from TB_APC_COMPANY_SUB where ji_code = x.ji_code ) as jiname, (select top (1) cd_nm from TB_KABM_CODE where div_cd = 'mem_div' and cd = mem_div ) as mem_div_nm, cptel,cpfax,cpost, cp_addr, cp_jibun, rprstt_kr,mb_no, rnum,tot_cnt
FROM ( select ROW_NUMBER() OVER( ORDER BY a.user_seq_no asc ) AS rnum, count(*) over() tot_cnt, user_seq_no, user_id, password, ssn, user_nm, (case when a.cp_code is null or a.cp_code = '' then a.CORP_NM else b.company end) as corp_nm, (case when a.mem_div = '4' then a.user_id else b.bsns_no end) as corp_reg_no, addr, tel_no, a.email, a.cp_code, a.ill_no, a.mem_div, a.building_nm, a.building_addr, a.zipcode, a.building_zipcode, a.post_zipcode, a.post_addr, a.post_req, a.post_tel_no, a.remark, a.account_nm, a.trans_yn, a.birth_yyyy, a.birth_mm, a.birth_dd, a.corp_tel_no, a.corp_fax_no, a.building_tel_no, a.building_fax_no, a.sex, '('+b.cpost+')'+ isnull(b.cp_addr,'') + ' '+ isnull(b.cp_jibun,'') as addr_nm, b.hcode, b.ji_code, b.cptel,b.cpfax,b.cpost, b.cp_addr, b.cp_jibun, b.rprstt_kr, replace(replace(b.mb_no , '제', '' ), '호', '') mb_no from tb_cyber_member a LEFT OUTER JOIN tb_mb_master b ON a.cp_code = b.cp_code and a.ill_no = b.ill_no where 1=1 $strHcode $strJicode $strUserName $strUserId $strCorpName $strMemDiv
) x WHERE rnum > (?-1) * ?
